<?php
require_once __DIR__.'/../includes/db.php';
$u=require_user();$id=trim($_GET['request']??'');if(!$id){http_response_code(400);exit('Request id required.');}
$st=db()->prepare("SELECT d.*,h.status,u.name,u.email,u.rdi_member_id FROM hr_documents d JOIN hr_requests h ON h.id=d.request_id JOIN users u ON u.id=d.user_id WHERE d.request_id=? LIMIT 1");$st->execute(array($id));$doc=$st->fetch();
if(!$doc||$doc['status']!=='Approved'){http_response_code(404);exit('Approved document not found.');}
if($doc['user_id']!==$u['id']&&!has_permission($u,'manage_hr_requests')){http_response_code(403);exit('Permission denied.');}
header('Content-Type: text/html; charset=utf-8');
$c=nl2br(htmlspecialchars($doc['content'],ENT_QUOTES,'UTF-8'));
?><!doctype html><html><head><meta charset="utf-8"><title><?=htmlspecialchars($doc['document_type'])?> - <?=htmlspecialchars($doc['document_number'])?></title><style>body{font-family:Arial,sans-serif;background:#eee;margin:0;padding:30px}.paper{max-width:800px;margin:auto;background:#fff;padding:55px 65px;box-shadow:0 10px 35px #0002;line-height:1.7}.head{border-bottom:3px solid #ee6c1a;margin-bottom:30px;padding-bottom:18px}.head h1{margin:0}.num{color:#666}.actions{text-align:center;margin:18px}@media print{body{background:#fff;padding:0}.paper{box-shadow:none;max-width:none}.actions{display:none}}</style></head><body><div class="actions"><button onclick="window.print()">Print / Save as PDF</button></div><div class="paper"><div class="head"><h1>RDI Innovators</h1><div class="num"><?=htmlspecialchars($doc['document_type'])?> · <?=htmlspecialchars($doc['document_number'])?></div></div><div><?=$c?></div><?php if(!empty($doc['signed_at'])): ?><div style="margin-top:45px;padding-top:18px;border-top:1px solid #ccc"><b>Member acknowledgement / signature</b><br><?=htmlspecialchars($doc['signed_by_name'])?><br><small>Signed internally on <?=htmlspecialchars($doc['signed_at'])?></small></div><?php endif; ?></div></body></html>
